package android.net;import java.net.URI;public class Uri {private URI uri;private Uri(String v){uri=URI.create(v);}public static Uri parse(String v){return new Uri(v);}public String getScheme(){return uri.getScheme();}public String getHost(){return uri.getHost();}public String getPath(){return uri.getPath();}public String getUserInfo(){return uri.getUserInfo();}public int getPort(){return uri.getPort();}public String toString(){return uri.toString();}}
